  "请读取资源清单": "リソース一覧を読み込んでください",
  "手动选择 {0} 项，自动包含 {1} 项，共 {2} MB；外部依赖 {3} 项。": "選択 {0} 件、自動追加 {1} 件、合計 {2} MB。外部依存 {3} 件。",
  "勾选对象或素材后，可导出包含 UUID、原始文件与元数据的资源包。": "オブジェクトや素材を選び、UUID・元ファイル・メタデータを含めてエクスポートできます。",
  "将导入 {0} 个对象、{1} 个素材；新增 {2} 个文件，复用 {3} 个相同文件。": "オブジェクト {0} 件、素材 {1} 件をインポートします。ファイル {2} 件を追加し、同一ファイル {3} 件を再利用します。",
