  "正在预览新对象…": "新規オブジェクトをプレビュー中…",
  "正在保存新对象…": "新規オブジェクトを保存中…",
  "新对象已保存。": "新規オブジェクトを保存しました。",
  "新对象已保存，但文档预览更新失败，请重新构建。": "新規オブジェクトを保存しましたが、文書プレビューを更新できませんでした。再構築してください。",
  "新对象已保存，请刷新核对内容。": "新規オブジェクトを保存しました。更新して内容を確認してください。",
  "保存位置已被使用，请更换原文路径后重新预览。": "保存先はすでに使用されています。原文のパスを変更して再度プレビューしてください。",
  "请使用文档目录内的有效路径，支持 Markdown、TXT、JSON 或 YAML。": "文書フォルダー内の有効なパスを指定してください。Markdown、TXT、JSON、YAML に対応しています。",
  "原文与文件格式不符，请检查 JSON 或 YAML 语法。": "原文がファイル形式と一致しません。JSON または YAML の構文を確認してください。",
  "对象类型已变化。草稿仍保留，请复制内容后刷新。": "オブジェクトの種類が変更されました。下書きは保持されています。内容をコピーしてから更新してください。",
  "原文路径": "原文のパス",
  "取消创建": "作成をキャンセル",
  "只显示已保存内容。编辑模式下可创建对象、修改属性、添加关系或绑定资源。": "保存済みの内容を表示します。編集モードではオブジェクトの作成、プロパティの編集、関係の追加、リソースの割り当てができます。",
  "有未保存的对象修改，确定丢弃？": "オブジェクトの未保存の変更を破棄しますか？",
  "绑定资源": "リソースを割り当て",
  "暂无已登记资源，请先在素材管理中导入。": "登録済みのリソースがありません。先に素材管理でインポートしてください。",
  "选择已登记资源并填写用途；离线资源也可绑定，文件内容尚未校验。": "登録済みのリソースを選び、用途を入力します。オフラインのリソースも割り当てられます。ファイルの内容は未検証です。",
  "目标资源": "割り当てるリソース",
  "资源用途（如 portrait、voice、attachment）": "リソースの用途（例：portrait、voice、attachment）",
  "预览绑定": "割り当てをプレビュー",
  "保存绑定": "割り当てを保存",
  "将添加的资源绑定": "追加するリソースの割り当て",
  "正在预览资源绑定…": "リソースの割り当てをプレビュー中…",
  "正在保存资源绑定…": "リソースの割り当てを保存中…",
  "资源绑定已保存。": "リソースの割り当てを保存しました。",
  "资源绑定已保存，但文档预览更新失败，请重新构建。": "リソースの割り当ては保存されましたが、文書プレビューの更新に失敗しました。インデックスを再構築してください。",
  "资源绑定已保存，请刷新核对内容。": "リソースの割り当てを保存しました。更新して内容を確認してください。",
  "工程版本已变化。资源绑定草稿仍保留，请记下选择后刷新，再重新预览。": "プロジェクトのバージョンが変更されました。リソース割り当ての下書きは保持されています。選択内容を控えてから更新し、再度プレビューしてください。",
  "此资源已绑定到该用途，请选择其他资源或用途。": "このリソースはすでにその用途に割り当てられています。別のリソースまたは用途を選んでください。",
  "请选择已登记资源和原文可用的对象。": "登録済みのリソースと、原文を読み取れるオブジェクトを選んでください。",
  "资源绑定请求未完成。草稿仍保留，请核对保存结果后重新预览。": "リソースの割り当て要求が完了しませんでした。下書きは保持されています。保存結果を確認してから再度プレビューしてください。",
