  "软件设计": "ソフトウェア設計",
  "从一个通用文档类型开始，按需添加自己的类型和模板。": "汎用ドキュメントから始め、必要に応じて独自の種類やテンプレートを追加できます。",
  "角色、故事、地点、组织与设定，适合人物和世界观创作。": "キャラクター、物語、場所、組織、設定を使って、人物や世界観を創作できます。",
  "组件、接口、流程与验证文档，用于设计和梳理软件工程。": "コンポーネント、インターフェース、フロー、検証の文書でソフトウェア設計を整理できます。",
  "类型和模板将复制到新工程，各工程可独立修改。下一步选择保存位置。": "種類とテンプレートは新しいプロジェクトにコピーされ、個別に編集できます。次に保存先を選択します。",
  "工程模板包格式无效": "プロジェクトテンプレートパッケージの形式が無効です",
  "工程模板包的类型与模板文件不匹配": "プロジェクトの種類とテンプレートファイルが一致しません",
  "工程模板目录格式无效": "プロジェクトテンプレート一覧の形式が無効です",
  "工程模板标识重复": "プロジェクトテンプレートの ID が重複しています",
  "工程模板目录缺少默认模板": "プロジェクトテンプレート一覧に既定のテンプレートがありません",
  "工程模板不存在，请重新选择": "プロジェクトテンプレートが見つかりません。選択し直してください。",
  "游戏": "ゲーム",
  "文学": "文学",
  "戏剧": "演劇",
  "角色、能力、道具、关卡、任务、阵营与规则，适合游戏世界和玩法设计。": "キャラクター、能力、アイテム、ステージ、クエスト、陣営、ルールで、ゲームの世界や遊びを設計できます。",
  "人物、大纲、篇章、地点、组织与设定，适合小说和其他文学创作。": "登場人物、あらすじ、章、場所、組織、設定を使って、小説などの文学作品を創作できます。",
  "人物、幕、场、舞台提示与道具，适合剧本和舞台叙事创作。": "登場人物、幕、場、ト書き、小道具を使って、戯曲や舞台の物語を創作できます。",
