  "查询构建工具版本超时，请检查工具配置。": "ビルドツールのバージョン取得がタイムアウトしました。ツール設定を確認してください。",
  "从已保存的场景生成独立产物。关闭面板后任务继续，可随时返回查看。": "保存済みのシーンから独立した成果物を生成します。パネルを閉じても処理は続行され、いつでも進捗を確認できます。",
  "请先保存或结束编辑草稿，再检查、构建或运行。当前草稿会保留。": "検証・ビルド・実行の前に下書きを保存するか編集を終了してください。現在の下書きは保持されます。",
