  "叙述声音": "語り口",
  "舞台目标": "舞台上の目的",
  "表演提示": "演技の指示",
  "arrows": "矢印キー",
  "none": "入力なし",
  "场景引用的投影无效，请检查投影原文。": "シーンが参照する投影が無効です。投影の原文を確認してください。",
  "投影的来源对象不可读取或不是普通对象，请检查来源。": "投影の元オブジェクトを読み込めないか、通常のオブジェクトではありません。参照元を確認してください。",
  "投影缺少来源关系，请检查对象登记。": "投影の元オブジェクトとの関係がありません。登録を確認してください。",
  "此投影不支持当前二维场景，请选择兼容的游戏投影。": "この投影は現在の 2D シーンに対応していません。対応するゲーム投影を選択してください。",
  "编辑投影配置": "投影設定を編集",
  "编辑时锁定来源对象、身份、子模板、文档类型与路径；只修改标题和配置。": "元オブジェクト、識別子、サブテンプレート、文書タイプ、パスは固定です。タイトルと設定のみ変更できます。",
  "更换或移除图片会保留旧资源绑定，以免已有场景的显式图片覆盖失效。素材原文件不会删除。": "画像を差し替えたり解除したりしても、既存シーンの画像指定を維持するため以前のリソース紐付けは残ります。素材ファイルは削除されません。",
  "投影已不存在。草稿保留，请返回对象核对。": "投影が存在しません。下書きは保持されています。オブジェクト一覧に戻って確認してください。",
  "将保存的投影": "保存する投影",
  "已核对，当前保存的投影配置与提交内容一致。": "確認しました。保存済みの投影設定は送信した内容と一致しています。",
  "投影配置已保存。返回对象查看，重新构建后生效。": "投影設定を保存しました。オブジェクトに戻って確認できます。変更は再ビルド後に反映されます。",
  "投影配置已保存，但目录刷新失败。请刷新核对，勿重复提交。": "投影設定は保存されましたが、文書一覧を更新できませんでした。再送信せず、更新して確認してください。",
  "投影的来源、模板或位置已变化。草稿保留，请返回对象重新打开。": "投影の参照元、テンプレート、または場所が変更されました。下書きは保持されています。オブジェクトに戻り、開き直してください。",
  "当前保存内容与上次提交不同。草稿保留，请核对后重新预览。": "保存済みの内容が前回の送信内容と異なります。下書きは保持されています。確認後、再度プレビューしてください。",
  "修改标题或配置后预览，确认原文与图片绑定再保存。": "タイトルや設定を変更したら、原文と画像の紐付けをプレビューしてから保存してください。",
  "正在保存投影配置与图片绑定…": "投影設定と画像の紐付けを保存中…",
  "场景已不存在。草稿保留，请返回构建面板核对。": "シーンが存在しません。下書きは保持されています。ビルド画面に戻って確認してください。",
  "编辑时锁定场景身份、文档类型与路径；可修改名称、画布和场景中的对象。": "シーンの識別子、文書の種類とパスは変更できません。名前、画面設定、シーン内のオブジェクトを編集できます。",
  "修改场景会保留已有对象关系与图片绑定。移除场景对象或换图不会删除原对象和素材。": "既存のオブジェクト関係と画像の関連付けは保持されます。シーンからの除去や画像の変更で元のオブジェクトや素材が削除されることはありません。",
  "在此场景覆盖图片": "このシーンで画像を上書き",
  "在此场景覆盖尺寸": "このシーンでサイズを上書き",
  "在此场景覆盖颜色": "このシーンで色を上書き",
  "在此场景覆盖速度": "このシーンで速度を上書き",
  "在此场景覆盖控制": "このシーンで操作を上書き",
  "位置属于场景。勾选单项覆盖可只修改该场景中的值，其他字段继续跟随投影。图片覆盖选择不使用图片可关闭继承图片。": "位置はシーン固有の設定です。項目ごとに上書きを選択すると、このシーンの値だけを変更できます。他の項目は投影を継承します。画像の上書きで「画像を使用しない」を選ぶと継承画像を非表示にできます。",
  "已核对，当前保存的场景与提交内容一致。": "保存済みのシーンが送信内容と一致することを確認しました。",
  "场景修改已保存。返回构建面板重新检查计划并构建。": "シーンの変更を保存しました。ビルド画面に戻り、計画を再確認してビルドしてください。",
  "场景修改已保存，但目录或构建列表刷新失败。请刷新核对，勿重复提交。": "シーンの変更は保存されましたが、文書またはビルド一覧を更新できませんでした。再送信せず、更新して確認してください。",
  "编辑二维场景": "2D シーンを編集",
  "将保存的场景": "保存するシーン",
  "场景的类型或位置已变化。草稿保留，请返回构建面板重新打开。": "シーンの種類または場所が変わりました。下書きは保持されています。ビルド画面に戻って開き直してください。",
  "读取场景原文": "シーンの原文を読み込む",
  "修改场景后预览，确认原文与依赖再保存。": "シーンを編集してプレビューし、原文と依存関係を確認して保存してください。",
  "编辑场景": "シーンを編集",
  "场景预览": "シーンプレビュー",
  "场景与构建选项卡": "シーンとビルドのタブ",
  "查看已保存场景的静态布局，无需构建或安装运行引擎。移动、输入和状态变化请使用运行测试。": "ビルドや実行エンジンのインストールなしで、保存済みシーンの配置を確認できます。移動・入力・状態変化は実行テストで確認してください。",
  "存在未保存草稿；预览仍使用上次保存的场景和投影。": "未保存の下書きがあります。プレビューには最後に保存したシーンと投影を使用します。",
  "预览已保存场景": "保存済みシーンをプレビュー",
