  "未创建运行会话": "実行セッション未作成",
  "预期位置：{0} · 每轴容差：{1}": "期待位置：{0} · 各軸の許容差：{1}",
  "实际位置：{0}": "実際の位置：{0}",
  "预期状态：{0} · 实际状态：{1}": "期待状態：{0} · 実際の状態：{1}",
  "未检查": "未確認",
  "用例报告导出未完成，请重试。": "用例レポートの書き出しが完了しませんでした。再試行してください。",
  "读取用例报告": "用例レポートを読み取る",
  "编辑共享片段": "共有フラグメントを編集",
  "修改会作用于引用此片段的多个放置；局部覆盖仍优先。": "変更はこのフラグメントを参照する複数の配置に適用されます。ローカルの上書き設定が引き続き優先されます。",
  "修改": "変更",
  "修改：{0}": "変更：{0}",
  "片段声明字段": "フラグメントの宣言フィールド",
  "只显示片段原文声明的值。未声明字段留空；勾选修改后才会设置，不会改动其他字段的继承或局部覆盖。": "フラグメントの原文で宣言した値だけを表示します。未宣言のフィールドは空欄です。「変更」を選んだフィールドだけを設定し、他の継承やローカルの上書きは維持します。",
  "请选择": "選択してください",
  "共享片段的引用实例": "共有フラグメントを参照するインスタンス",
  "应用只更新原文草稿；仍需在编辑器保存。": "適用すると原文の下書きを更新します。変更の保存にはエディターでの保存が必要です。",
  "检查共享片段修改": "フラグメントの変更を確認",
  "参与共享修改：{0}": "共有の変更を適用：{0}",
  "局部覆盖仍优先：{0}": "ローカルの上書きを優先：{0}",
  "勾选字段后显示该实例的修改影响。": "フィールドを選ぶと、このインスタンスへの影響を表示します。",
  "引用实例：{0}；尚未选择修改字段。": "参照インスタンス：{0}。変更するフィールドは未選択です。",
  "引用实例：{0}；{1} 个实例参与所选字段的共享修改。": "参照インスタンス：{0}。{1} 個に選択フィールドの共有変更を適用します。",
  "所有引用实例均有局部覆盖；本次只更新片段声明。": "参照する全インスタンスにローカルの上書きがあります。今回はフラグメントの宣言だけを更新します。",
  "共享片段修改尚未应用到原文草稿。": "フラグメントの変更はまだ原文の下書きに適用していません。",
  "原文或预览已变化，请重新预览后编辑共享片段。": "原文またはプレビューが変わりました。再度プレビューしてから共有フラグメントを編集してください。",
  "片段已声明此字段。": "このフィールドはフラグメントで宣言されています。",
