  "尺寸 Z": "サイズ Z",
  "当前会话不支持工程交付": "このセッションではプロジェクトを引き渡せません。",
  "生成工程或来源已变化，请返回工程详情重新核对。": "生成プロジェクトまたは元データが変更されました。詳細に戻って再確認してください。",
  "有任务正在处理，请稍后再准备交付包。": "別の処理が実行中です。完了後に配布パッケージを準備してください。",
  "为场景添加行为": "シーンに動作を追加",
  "添加场景行为": "シーンの動作を追加",
  "为已保存场景的一份实例创建行为文档，并一起登记关联关系。此操作不运行脚本。": "保存済みシーンの一つのインスタンスに動作文書を作成し、関連をまとめて登録します。スクリプトは実行されません。",
  "本次声明使用 Godot 4 / GDScript；创建不要求已安装 Godot。保存后可在行为编辑器中添加参数、信号和更多绑定。": "この宣言は Godot 4 / GDScript を使用します。作成時に Godot のインストールは不要です。保存後、動作エディターでパラメーター、シグナル、バインドを追加できます。",
  "没有可用的已登记 TXT 脚本。请返回主编辑器，新建并保存 TXT 文档后再添加行为。": "利用できる登録済み TXT スクリプトがありません。メインエディターで TXT 文書を新規作成して保存してから、動作を追加してください。",
  "行为文档设置": "動作文書の設定",
  "已登记脚本": "登録済みスクリプト",
  "创建行为审阅": "新しい動作の確認",
  "保存会新建下列完整原文和文档登记，并更新场景登记中的行为关系；场景正文与脚本正文保持原样。": "保存すると、以下の原文全体と文書の登録を作成し、シーンの登録に動作の関連を追加します。シーンとスクリプトの原文は保持されます。",
  "将登记的关系": "登録する関連",
  "将创建的完整原文": "作成する原文全体",
  "审阅新行为": "新しい動作を確認",
  "保存行为与关系": "動作と関連を保存",
  "打开行为原文": "動作の原文を開く",
  "行为尚未保存，请先审阅原文与关系。": "動作は未保存です。先に原文と関連を確認してください。",
  "场景：{0} · {1}": "シーン：{0} · {1}",
  "新文档身份：{0} · 绑定身份：{1}": "新しい文書 ID：{0} · バインド ID：{1}",
  "无法核对行为创建目录，请返回工程检查。": "動作作成の一覧を検証できません。プロジェクトに戻って確認してください。",
  "请选择当前工程中的文档类型、实例和脚本。": "現在のプロジェクトから文書の種類、インスタンス、スクリプトを選択してください。",
  "行为保存回执不匹配，请重新核对工程，勿重复创建。": "動作の保存結果が一致しません。再作成せず、プロジェクトを確認してください。",
  "行为与关系已保存。打开原文后可继续编辑参数和信号。": "動作と関連を保存しました。原文を開いてパラメーターとシグナルを編集できます。",
  "行为已保存，但目录刷新失败。请重新读取工程，勿重复创建。": "動作は保存されましたが、一覧を更新できませんでした。再作成せず、プロジェクトを再読込してください。",
  "正在读取行为创建目录…": "動作作成の一覧を読込中…",
  "保存结果尚未确认，请核对工程中的行为文档与关系，勿重复创建。": "保存結果を確認できません。再作成せず、プロジェクト内の動作文書と関連を確認してください。",
  "选择实例和脚本后，审阅新文档与关联关系。": "インスタンスとスクリプトを選び、新しい文書と関連を確認してください。",
  "无法读取工程，行为设置已保留，请重试。": "プロジェクトを読み取れません。動作の設定は保持されています。再試行してください。",
  "正在保存行为文档与关系…": "動作文書と関連を保存中…",
  "正在审阅行为文档与关系…": "動作文書と関連を確認中…",
  "行为创建已审阅，请确认完整原文与全部关联关系后保存。": "動作の作成を確認しました。原文全体とすべての関連を確認してから保存してください。",
  "工程已变化。行为设置已保留，请重新读取工程并审阅。": "プロジェクトが変更されました。設定を保持したまま再読込し、もう一度確認してください。",
  "行为请求未完成。设置已保留，请检查后重试。": "動作の処理が完了しませんでした。設定は保持されています。確認して再試行してください。",
  "来源或会话已变化，请返回构建后重新打开行为创建。": "元データまたはセッションが変更されました。ビルド画面に戻り、動作の作成を開き直してください。",
  "丢弃本次行为创建设置？尚未提交的内容不会写入工程。": "今回の動作作成の設定を破棄しますか？未送信の内容はプロジェクトに書き込まれません。",
  "行为已保存，但原文未打开。请返回编辑器按路径查找。": "動作は保存されましたが、原文を開けませんでした。エディターに戻り、パスで探してください。",
  "无法打开已创建的行为原文，请刷新目录后重试。": "作成した動作の原文を開けません。一覧を更新して再試行してください。",
  "已打开行为原文，可继续编辑参数与信号。": "動作の原文を開きました。パラメーターとシグナルを編集できます。",
  "原文诊断：{0}": "原文の診断：{0}",
  "错误": "エラー",
  "警告": "警告",
  "提示": "情報",
  "关闭诊断": "診断を閉じる",
  "第 {0} 行，第 {1} 列": "{0}行、{1}列",
  "原文已修改，此诊断尚未重新检查。": "原文が編集されました。この診断はまだ再確認されていません。",
  "此位置来自已核对的原文；修改后请重新检查。": "この位置は確認済みの原文と一致しています。編集後は再確認してください。",
  "诊断所依据的原文已变化，位置已失效。请重新检查。": "診断の対象となった原文が変更されています。位置情報は古いため、再確認してください。",
  "此诊断只有大致位置，请结合原文核对。": "この診断にはおおよその位置しかありません。原文と照らし合わせて確認してください。",
  "此诊断没有可用的原文位置，请结合详情核对。": "この診断には利用できる原文の位置情報がありません。詳細を確認してください。",
